package com.ruoyi.hexu;
import java.util.*;
import java.sql.Timestamp;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.BusinessException.require;

/** Store handover moves future ownership and approved inventory/relations; historical money stays put. */
public final class HexuShopLifecycle {
 private final HexuStore db;
 public HexuShopLifecycle(HexuStore db){this.db=db;}
 public Map<String,Object> readiness(long shop){Map<String,Object>s=db.one("select * from hx_shop where id=?",shop);long open=db.jdbc().queryForObject("select count(*) from hx_order where (shop_id=? or destination_shop_id=?) and status in ('UNPAID','PAID','SHIPPED')",Long.class,shop,shop),refunds=db.jdbc().queryForObject("select count(*) from hx_refund where shop_id=? and status not in ('SUCCESS','CLOSED','REJECTED')",Long.class,shop),wallets=db.jdbc().queryForObject("select count(*) from hx_wallet where shop_id=? and (available<>0 or frozen<>0)",Long.class,shop),withdrawals=db.jdbc().queryForObject("select count(*) from hx_withdrawal where shop_id=? and status in ('PENDING','APPROVED','PROCESSING')",Long.class,shop),points=db.jdbc().queryForObject("select count(*) from hx_points where shop_id=? and (available<>0 or pending_reclaim<>0 or frozen=true)",Long.class,shop);long windows=0;for(Map<String,Object>l:db.jdbc().queryForList("select l.snapshot_json,o.completed_at from hx_order_line l join hx_order o on o.id=l.order_id where o.shop_id=? and o.status='COMPLETED' and l.refunded_qty<l.qty",shop)){Map<String,Object>snap=db.parse(l.get("snapshot_json"));long days=snap.containsKey("afterSalesDays")?number(snap,"afterSalesDays"):7;if(((Timestamp)l.get("completed_at")).getTime()+days*86400000L>System.currentTimeMillis())windows++;}return map("shop",map("id",s.get("id"),"name",s.get("name"),"ownerId",s.get("owner_id"),"status",s.get("status")),"openOrders",open,"openRefunds",refunds,"unsettledWallets",wallets,"openWithdrawals",withdrawals,"afterSalesWindows",windows,"pointAccounts",points,"ready",open+refunds+wallets+withdrawals+windows==0);}
 private Map<String,Object> manifest(long shop){return map("shop",db.one("select * from hx_shop where id=?",shop),"agents",db.jdbc().queryForList("select id,member_id,parent_id,rank_no,status from hx_agent where shop_id=? order by id",shop),"bindings",db.jdbc().queryForList("select member_id,agent_id from hx_binding where shop_id=? order by member_id",shop),"inventory",db.jdbc().queryForList("select id,available,locked,defective from hx_sku where shop_id=? order by id",shop),"wallets",db.jdbc().queryForList("select member_id,available,frozen from hx_wallet where shop_id=? order by member_id",shop),"points",db.jdbc().queryForList("select member_id,available,pending_reclaim,frozen from hx_points where shop_id=? order by member_id",shop));}
 public Map<String,Object> prepare(Actor actor,long shop,Map<String,Object>input){db.manage(actor,shop,"OWNER");db.one("select id from hx_shop where id=? for update",shop);Map<String,Object>s=db.shop(shop);require("DEALER".equals(str(s,"kind")),"公司直营与批发商城不能通过经销商交接流程变更");String mode=str(input,"operation");require(Arrays.asList("TRANSFER","MERGE","CLOSE").contains(mode),"请选择转让、合并或停业");require(str(input,"reason").trim().length()>=2,"请记录商城交接原因");require(db.jdbc().queryForObject("select count(*) from hx_document where shop_id=? and kind='shop_transfer' and status in ('PENDING','SCHEDULED')",Long.class,shop)==0,"商城已有进行中的交接申请");Map<String,Object>ready=readiness(shop);require(bool(ready,"ready"),"请先处理未完成订单、售后期限、余额和提现后再提交交接");require("TRANSFER".equals(mode)||number(ready,"pointAccounts")==0,"停业或合并前需处理全部商城积分和待追回记录");Map<String,Object>b=new LinkedHashMap<>(input);String at=str(input,"effectiveAt");long effective=at.isEmpty()?System.currentTimeMillis():at.matches("[0-9]{12,13}")?Long.parseLong(at):Timestamp.valueOf(at.length()==10?at+" 00:00:00":at).getTime();require(effective>=System.currentTimeMillis()-60000,"商城交接不能追溯生效，请选择将来时间或留空立即生效");b.put("effectiveTimestamp",effective);b.put("sourceOwner",s.get("owner_id"));b.put("manifest",manifest(shop));if("MERGE".equals(mode)){for(Map<String,Object>peer:db.jdbc().queryForList("select body_json from hx_document where kind='peer_authorization' and status='ACTIVE'")){Map<String,Object>p=db.parse(peer.get("body_json"));require(db.jdbc().queryForObject("select count(*) from hx_agent where shop_id=? and id in (?,?)",Long.class,shop,number(p,"parentAgentId"),number(p,"childAgentId"))==0,"存在跨商城同级分红关系，需先完成平台关系处置后合并");}long target=number(input,"targetShopId");Map<String,Object>t=db.shop(target);require(target!=shop&&number(t,"owner_id")==number(s,"owner_id")&&"DEALER".equals(str(t,"kind")),"合并目标须为同一拥有者的其他经销商商城");b.put("targetManifest",manifest(target));}if("TRANSFER".equals(mode)){Map<String,Object>next=number(input,"newOwnerAgentId")>0?db.optional("select * from hx_agent where id=? and shop_id=? and status='ACTIVE'",number(input,"newOwnerAgentId"),shop):db.agent(number(input,"newOwnerId"),shop);require(next!=null&&number(next,"member_id")!=number(s,"owner_id")&&number(next,"rank_no")>=2,"新拥有者必须是本商城符合开店职级的其他代理");long maximum=db.jdbc().queryForObject("select max(rank_no) from hx_agent where shop_id=? and status='ACTIVE'",Long.class,shop);require(number(next,"rank_no")>=maximum,"新拥有者职级不能低于交接团队最高职级");b.put("newOwnerAgentId",next.get("id"));b.put("newOwnerId",next.get("member_id"));}if("CLOSE".equals(mode))require(db.jdbc().queryForObject("select coalesce(sum(available+locked+defective),0) from hx_sku where shop_id=?",Long.class,shop)==0,"停业前请完成全部实物库存处置");return b;}
 public void apply(Actor actor,long source,Map<String,Object>b){String mode=str(b,"operation");long target="MERGE".equals(mode)?number(b,"targetShopId"):source;for(long id:new TreeSet<>(Arrays.asList(source,target)))db.one("select id from hx_shop where id=? for update",id);Map<String,Object>s=db.shop(source);require(number(s,"owner_id")==number(b,"sourceOwner"),"商城拥有者已变化，请重新提交交接");for(Map<String,Object>o:db.jdbc().queryForList("select id from hx_order where shop_id=? or destination_shop_id=? order by id for update",source,source)){}for(String table:Arrays.asList("hx_sku","hx_wallet","hx_points","hx_agent","hx_binding"))db.jdbc().queryForList("select * from "+table+" where shop_id=? for update",source);require(db.json(manifest(source)).equals(db.json(b.get("manifest"))),"商城库存、余额或代理客户名单已变化，请重新提交交接");require(bool(readiness(source),"ready"),"商城仍有未完成的交易或账务事项");
 if("TRANSFER".equals(mode)){Map<String,Object>next=db.one("select * from hx_agent where id=? and shop_id=? and status='ACTIVE'",number(b,"newOwnerAgentId"),source),old=db.agent(number(s,"owner_id"),source);require(next!=null&&old!=null&&number(next,"rank_no")>=2,"交接代理身份无效");db.jdbc().update("update hx_agent set parent_id=null where id=?",next.get("id"));db.jdbc().update("update hx_agent set parent_id=? where id=?",next.get("id"),old.get("id"));db.jdbc().update("update hx_shop set owner_id=?,merchant_no=null,payment_ready=false,status='ONBOARDING' where id=?",number(b,"newOwnerId"),source);db.jdbc().update("update hx_document set status='ARCHIVED' where shop_id=? and kind in ('peer_authorization','merchant_application','merchant_authorization') and status='ACTIVE'",source);}
 else if("MERGE".equals(mode)){Map<String,Object>dest=db.shop(target);require(number(dest,"owner_id")==number(s,"owner_id")&&db.json(manifest(target)).equals(db.json(b.get("targetManifest"))),"目标商城拥有者或交接数据发生变化");Map<String,Object>sourceRoot=db.agent(number(s,"owner_id"),source),targetRoot=db.agent(number(dest,"owner_id"),target);require(sourceRoot!=null&&targetRoot!=null,"商城拥有者代理身份不完整");List<Map<String,Object>>agents=db.jdbc().queryForList("select * from hx_agent where shop_id=? and status='ACTIVE' order by id",source);for(Map<String,Object>a:agents)if(number(a,"id")!=number(sourceRoot,"id")){require(db.agent(number(a,"member_id"),target)==null,"目标商城存在重复代理身份，请先处理冲突");require(number(a,"rank_no")<=number(targetRoot,"rank_no"),"目标商城拥有者职级不足");}List<Map<String,Object>>bindings=db.jdbc().queryForList("select * from hx_binding where shop_id=? order by member_id",source);for(Map<String,Object>v:bindings)require(db.optional("select member_id from hx_binding where shop_id=? and member_id=?",target,v.get("member_id"))==null,"目标商城已有客户绑定，需先处理冲突");
 for(Map<String,Object>p:db.jdbc().queryForList("select * from hx_sku where shop_id=? order by id",source)){require(number(p,"locked")==0,"存在锁定库存");db.one("select id from hx_sku where shop_id=? and id=? for update",target,p.get("id"));int qty=(int)number(p,"available"),defect=(int)number(p,"defective");if(qty>0){db.inventory(source,str(p,"id"),-qty,0,"SHOP_MERGE_OUT",str(b,"documentId"));db.inventory(target,str(p,"id"),qty,0,"SHOP_MERGE_IN",str(b,"documentId"));}if(defect>0){db.jdbc().update("update hx_sku set defective=0 where shop_id=? and id=?",source,p.get("id"));db.jdbc().update("insert into hx_inventory_log(shop_id,sku_id,available_delta,locked_delta,defective_delta,reason,reference_id) values(?,?,0,0,?,'SHOP_MERGE_OUT',?)",source,p.get("id"),-defect,str(b,"documentId"));db.defective(target,str(p,"id"),defect,"SHOP_MERGE_IN",str(b,"documentId"));}}
 for(Map<String,Object>a:agents)if(number(a,"id")!=number(sourceRoot,"id"))db.jdbc().update("update hx_agent set shop_id=?,parent_id=? where id=?",target,number(a,"parent_id")==number(sourceRoot,"id")||number(a,"parent_id")==0?targetRoot.get("id"):a.get("parent_id"),a.get("id"));db.jdbc().update("update hx_agent set status='MIGRATED' where id=?",sourceRoot.get("id"));for(Map<String,Object>v:bindings)db.jdbc().update("update hx_binding set shop_id=?,agent_id=? where shop_id=? and member_id=?",target,number(v,"agent_id")==number(sourceRoot,"id")?targetRoot.get("id"):v.get("agent_id"),source,v.get("member_id"));db.jdbc().update("update hx_shop set status='MERGED',payment_ready=false where id=?",source);}
 else{require(number(readiness(source),"pointAccounts")==0,"商城积分尚未处理");db.jdbc().update("update hx_shop set status='CLOSED',payment_ready=false where id=?",source);}
 db.jdbc().update("update hx_invite set status='INACTIVE' where shop_id=?",source);db.audit(actor,source,"SHOP_"+mode,str(b,"documentId"),b.get("manifest"),map("source",manifest(source),"targetShopId",target));}
}
